import sys; sys.path.insert(0,'/home/user/squares/packing')
exec(open(sys.argv[1]).read().split("# the 20 active constraints")[0])  # reuse definitions from verify_chart.py
from devtools.assess_n5_rigidity import load_pose, active_contacts
pose = load_pose(); contacts = active_contacts(pose)
zero = {z: 0 for z in Z}
for idx, c in enumerate(contacts):
    g = wall_poly(c.moving, c.corner, c.wall) if c.kind == "wall" else pair_poly(c.moving, c.corner, c.host, c.edge)
    g = sp.expand(g)
    grad = [S(sp.diff(g, z).subs(zero)) for z in Z]
    nz = {str(z): str(v) for z, v in zip(Z, grad) if v != 0}
    t4 = Z[14]
    q = S(sp.diff(g, t4, t4).subs(zero))
    print(f"[{idx:2d}] {c.describe()}\n      g = {sp.collect(g, Z)}\n      grad(0) = {nz}   q_t4 = {q}")
